        "prompt": "Tiến hành thí nghiệm xà phòng hóa chất béo:<br>• Chuẩn bị: chất béo (dầu thực vật hoặc mỡ động vật), dung dịch NaOH 40%, dung dịch NaCl bão hoà; bát sứ, cốc thuỷ tinh, đũa thuỷ tinh, kiềng sắt, đèn cồn.<br>• Tiến hành:<br>− Cho khoảng 2 g chất béo và khoảng 4 mL dung dịch NaOH 40% vào bát sứ. Đun nhẹ hỗn hợp trong khoảng 10 phút và liên tục khuấy bằng đũa thuỷ tinh. Nếu thể tích nước giảm cần bổ sung thêm nước.<br>− Kết thúc phản ứng, đổ hỗn hợp vào cốc thuỷ tinh chứa khoảng 30 mL dung dịch NaCl bão hoà, khuấy nhẹ. Để nguội hỗn hợp, tách lấy khối xà phòng nổi lên ở trên.<br>Xét tính đúng/sai của các phát biểu sau:",
