        "question": "Một học sinh tiến hành làm thí nghiệm tráng bạc của glucose theo hai bước sau:<br>− Bước 1: Cho vào một ống nghiệm sạch 1 mL dung dịch AgNO<sub>3</sub> 1%, sau đó nhỏ tiếp từng giọt dung dịch NH<sub>3</sub> vào cho đến khi kết tủa vừa xuất hiện lại tan hết.<br>− Bước 2: Thêm tiếp 1 mL dung dịch glucose 1% vào ống nghiệm trên rồi đun nóng nhẹ.<br>Xét tính đúng/sai của các phát biểu sau:",
