        "question": "Cho các chất: saccharose, glucose, fructose, ethyl formate, formic acid và acetic aldehyde. Trong các chất trên, có bao nhiêu chất vừa có khả năng tham gia phản ứng tráng bạc vừa có khả năng phản ứng với Cu(OH)<sub>2</sub> ở điều kiện thường?",
