        "prompt": "Valine là một loại amino acid thiết yếu, cần được cung cấp từ nguồn thực phẩm bên ngoài, cơ thể không tự tổng hợp được. Khi cho 1,404 gam valine hòa tan trong nước được dung dịch. Dung dịch này phản ứng vừa đủ với 12 mL dung dịch NaOH có nồng độ C (mol/L), thu được 1,668 gam muối. Giá trị của C là bao nhiêu?",
        "question": "Valine là một loại amino acid thiết yếu, cần được cung cấp từ nguồn thực phẩm bên ngoài, cơ thể không tự tổng hợp được. Khi cho 1,404 gam valine hòa tan trong nước được dung dịch. Dung dịch này phản ứng vừa đủ với 12 mL dung dịch NaOH có nồng độ C (mol/L), thu được 1,668 gam muối. Giá trị của C là bao nhiêu?",
