        "question": "Now Ultra Omega-3 Fish Oil 90 là sản phẩm dầu cá được ưa chuộng trên thị trường. Mỗi viên dầu cá chứa 180 mg EPA (C<sub>20</sub>H<sub>30</sub>O<sub>2</sub>) và 120 mg DHA (C<sub>22</sub>H<sub>32</sub>O<sub>2</sub>). Hãy tính tổng số mol EPA và DHA có trong một lọ gồm 90 viên trên? (Kết quả làm tròn đến 3 chữ số thập phân).",
