        "question": "Phản ứng quang hợp tạo ra glucose cần được cung cấp năng lượng theo phương trình nhiệt hóa học:<br>6 CO<sub>2</sub> + 6 H<sub>2</sub>O + 673 kcal ⎯⎯(clorophyll, asmt)⎯→ C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> + 6 O2<br>Nếu có một cây xanh với tổng diện tích lá 100 dm², mỗi dm² nhận được 3000 cal năng lượng mặt trời trong 1 giờ và chỉ có 10% năng lượng đó tham gia phản ứng tổng hợp glucose, thì trong 10 giờ có x gam glucose được tạo thành. Xác định giá trị của x (làm tròn đến một chữ số thập phân).",
