        "type": "mcq",
        "prompt": "Giá trị pH mà khi đó amino acid có nồng độ ion lưỡng cực là cực đại được gọi là điểm đẳng điện (pI). Khi pH < pI thì amino acid tồn tại chủ yếu ở dạng cation (di chuyển về cực âm), còn khi pH > pI thì amino acid tồn tại chủ yếu ở dạng anion (di chuyển về cực dương). Cho các giá trị pI: glycine (6,0); glutamic acid (3,2); lysine (9,7). Trong các giá trị pH cho dưới đây, giá trị nào là tối ưu nhất để tách ba chất trên ra khỏi dung dịch hỗn hợp của chúng?",
        "question": "Giá trị pH mà khi đó amino acid có nồng độ ion lưỡng cực là cực đại được gọi là điểm đẳng điện (pI). Khi pH < pI thì amino acid tồn tại chủ yếu ở dạng cation (di chuyển về cực âm), còn khi pH > pI thì amino acid tồn tại chủ yếu ở dạng anion (di chuyển về cực dương). Cho các giá trị pI: glycine (6,0); glutamic acid (3,2); lysine (9,7). Trong các giá trị pH cho dưới đây, giá trị nào là tối ưu nhất để tách ba chất trên ra khỏi dung dịch hỗn hợp của chúng?",
        "options": {
          "A": "pH = 14,0.",
          "B": "pH = 9,7.",
          "C": "pH = 3,2.",
          "D": "pH = 6,0."
        },
        "answer": "D",
        "explanation": "Tại pH = 6,0:<br>• Glycine có pH = pI = 6,0 nên ở dạng ion lưỡng cực không tích điện, đứng yên không di chuyển.<br>• Glutamic acid có pI = 3,2 < 6,0 (pH > pI) nên tồn tại ở dạng anion mang điện âm, di chuyển về cực dương (+).<br>• Lysine có pI = 9,7 > 6,0 (pH < pI) nên tồn tại ở dạng cation mang điện dương, di chuyển về cực âm (-).<br>Do đó ba chất di chuyển theo ba hướng khác nhau, phân tách triệt để nhất.<br>Chọn <b>D</b>."
