        "question": "Insulin là hormone có tác dụng điều tiết lượng đường trong máu. Thủy phân một phần insulin thu được heptapeptide X mạch hở. Khi thủy phân không hoàn toàn X, thu được hỗn hợp chứa các peptide: Phe-Phe-Tyr, Pro-Lys-Thr, Tyr-Thr-Pro, Phe-Tyr-Thr. Nếu đánh số thứ tự đầu N là số 1, thì amino acid ở vị trí số 5 trong X có kí hiệu là",
