        "answer": "C",
        "explanation": "Số nguyên tử N trong Y: n(N) = (131 · 10,61%) / 14 = 1.<br>Số nguyên tử C: n(C) = (131 · 54,96%) / 12 = 6.<br>Số nguyên tử H: n(H) = (131 · 9,85%) / 1 = 13.<br>Số nguyên tử O: n(O) = (131 - 12·6 - 13·1 - 14·1) / 16 = 2.<br>Công thức phân tử của Y là C<sub>6</sub>H<sub>13</sub>NO<sub>2</sub>. Vì Y có nhóm amine ở đầu mạch và mạch không phân nhánh nên Y là 6-aminohexanoic acid: H2N-[CH2]5-COOH.<br>Phản ứng trùng ngưng Y thu được polyamide X (nylon-6 hay polycaproamide): -(NH-[CH<sub>2</sub>]<sub>5</sub>-CO)-ₙ.<br>Chọn <b>C</b>."
