        "question": "Củ sắn khô chứa 38% khối lượng là tinh bột, còn lại là các chất không có khả năng lên men thành ethyl alcohol. Lên men 1 tấn sắn khô với hiệu suất cả quá trình là 81%. Toàn bộ lượng alcohol sinh ra dùng để điều chế xăng E5 (chứa 5% thể tích alcohol). Biết khối lượng riêng của ethyl alcohol là 0,8 g/mL, thể tích xăng E5 thu được là bao nhiêu lít?",
