        "figure": "assets/images/quiz/chem/de3_p3_q1.png",
        "prompt": "Dầu gió xanh Thiên Thảo dùng để chủ trị cảm cúm, nhức đầu, côn trùng cắn. Thành phần một chai dầu 12 mL chứa 2,16 gam methyl salicylate. Methyl salicylate được điều chế theo phản ứng:<br>HOC6H4COOH + CH<sub>3</sub>OH ⎯⎯(H<sub>2</sub>SO<sub>4</sub> đặc, t°)⎯→ HOC6H4COOCH3 + H2O<br>Để sản xuất một triệu hộp dầu (mỗi hộp gồm 12 chai dầu trên) cần tối thiểu m tấn salicylic acid, với hiệu suất cả quá trình là 80%. Giá trị của m là bao nhiêu? (Làm tròn đến một chữ số thập phân).",
        "question": "Dầu gió xanh Thiên Thảo dùng để chủ trị cảm cúm, nhức đầu, côn trùng cắn. Thành phần một chai dầu 12 mL chứa 2,16 gam methyl salicylate. Methyl salicylate được điều chế theo phản ứng:<br>HOC6H4COOH + CH<sub>3</sub>OH ⎯⎯(H<sub>2</sub>SO<sub>4</sub> đặc, t°)⎯→ HOC6H4COOCH3 + H2O<br>Để sản xuất một triệu hộp dầu (mỗi hộp gồm 12 chai dầu trên) cần tối thiểu m tấn salicylic acid, với hiệu suất cả quá trình là 80%. Giá trị của m là bao nhiêu? (Làm tròn đến một chữ số thập phân).",
