        "prompt": "Tiến hành thí nghiệm phản ứng xà phòng hóa theo các bước sau đây:<br>• <b>Bước 1:</b> Cho vào bát sứ khoảng 1 gam mỡ (hoặc dầu thực vật) và 2 - 2,5 mL dung dịch NaOH 40%.<br>• <b>Bước 2:</b> Đun hỗn hợp sôi nhẹ và liên tục khuấy đều bằng đũa thủy tinh. Thỉnh thoảng thêm vài giọt nước cất để giữ cho thể tích của hỗn hợp không đổi.<br>• <b>Bước 3:</b> Sau 8 - 10 phút, rót thêm vào hỗn hợp 4 - 5 mL dung dịch NaCl bão hòa nóng, khuấy nhẹ rồi để nguội.<br>Phát biểu nào sau đây <b>sai</b>?",
