        "prompt": "Một thí nghiệm điện di hỗn hợp 3 amino acid gồm Glutamic acid (Glu), Alanine (Ala) và Lysine (Lys) ở pH = 6 được mô tả như hình bên. Thứ tự các amino acid ứng với các vệt được đánh dấu (1), (2), (3) là",
