        "prompt": "Trong công nghiệp chế biến đường từ mía sẽ tạo ra sản phẩm phụ, gọi là rỉ đường hay rỉ mật (chứa 90% saccharose). Người ta sử dụng rỉ đường để lên men tạo ra ethanol trong điều kiện thích hợp với hiệu suất của cả quá trình là 40%:<br>C<sub>12</sub>H<sub>22</sub>O<sub>11</sub> + H<sub>2</sub>O <sup>enzyme</sup>⟶ C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> (glucose) + C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> (fructose)<br>C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> <sup>enzyme</sup>⟶ 2C2H5OH + 2CO2<br>Khối lượng ethanol thu được từ 1 tấn rỉ đường mía theo 2 phương trình trên là",
        "options": {
          "A": "193,7 kg.",
          "B": "124,5 kg.",
          "C": "184,2 kg.",
          "D": "238,0 kg."
        },
        "answer": "A",
        "explanation": "• Trong 1 tấn (1000 kg) rỉ đường có: m(saccharose) = 1000 × 90% = 900 kg.<br>• Sơ đồ chuyển hóa tổng quát:<br>C<sub>12</sub>H<sub>22</sub>O<sub>11</sub> (342) ⟶ 2 C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> ⟶ 4 C<sub>2</sub>H<sub>5</sub>OH (4 × 46 = 184)<br>• Khối lượng ethanol thu được theo lý thuyết là:<br>m(lt) = (900 × 184) / 342 ≈ 484,21 kg.<br>• Vì hiệu suất của cả quá trình là 40%, khối lượng ethanol thực tế thu được là:<br>m(tt) = 484,21 × 40% = 193,68 kg ≈ 193,7 kg.<br>Chọn <b>A</b>."
