        "explanation": "• <b>a) Đúng:</b> Cinnamic acid tác dụng với methyl alcohol: C<sub>6</sub>H<sub>5</sub>–CH=CH–COOH + CH<sub>3</sub>OH ⇌ C<sub>6</sub>H<sub>5</sub>–CH=CH–COOCH<sub>3</sub> + H<sub>2</sub>O, do đó công thức cấu tạo của methyl cinnamate là C<sub>6</sub>H<sub>5</sub>–CH=CH–COOCH<sub>3</sub>.<br>• <b>b) Đúng:</b> Methyl cinnamate là ester đơn chức của alcohol thông thường, phản ứng xà phòng hóa theo tỉ lệ mol 1 : 1: C<sub>6</sub>H<sub>5</sub>–CH=CH–COOCH<sub>3</sub> + NaOH ⟶ C<sub>6</sub>H<sub>5</sub>–CH=CH–COONa + CH<sub>3</sub>OH.<br>• <b>c) Đúng:</b> Liên kết đôi –CH=CH– có 2 nhóm thế khác nhau ở mỗi nguyên tử carbon (–H khác –C<sub>6</sub>H<sub>5</sub> và –H khác –COOCH<sub>3</sub>) nên có 2 đồng phân hình học cis và trans.<br>• <b>d) Đúng:</b> Số mol cinnamic acid ban đầu là n = 29,6 / 148 = 0,2 mol. Số mol methyl cinnamate thu được là n = 16,2 / 162 = 0,1 mol. Hiệu suất phản ứng ester hóa là H = (0,1 / 0,2) × 100% = 50%."
