        "prompt": "Glutamic acid có vai trò quan trọng trong quá trình xây dựng cấu trúc tế bào của con người. Ngoài ra, muối monosodium glutamate còn được dùng chế biến gia vị thức ăn (bột ngọt hay mì chính). Glutamic acid có cấu trúc như hình vẽ bên dưới và có điểm đẳng điện pI = 3,2 (pI là giá trị pH mà khi đó amino acid có nồng độ ion lưỡng cực là cực đại; khi pH < pI amino acid tồn tại chủ yếu ở dạng cation, còn khi pH > pI thì tồn tại chủ yếu ở dạng anion).",
