        "label": "Câu 13",
        "type": "mcq",
        "prompt": "Cho các phát biểu sau:<br>(a) Chất béo được gọi chung là triglyceride.<br>(b) Chất béo nhẹ hơn nước, không tan trong nước nhưng tan nhiều trong các dung môi hữu cơ.<br>(c) Phản ứng thủy phân chất béo trong môi trường acid là phản ứng thuận nghịch.<br>(d) Ở nhiệt độ thường, chất béo chứa nhiều gốc acid béo không no thường ở thể rắn.<br>Số phát biểu đúng là",
