        "answer": "D",
        "explanation": "• (a) <b>Đúng:</b> Chất béo là triester của glycerol với các acid béo, được gọi chung là triglyceride.<br>• (b) <b>Đúng:</b> Chất béo nhẹ hơn nước, không tan trong nước nhưng tan tốt trong các dung môi hữu cơ không phân cực.<br>• (c) <b>Đúng:</b> Phản ứng thủy phân chất béo trong môi trường acid là phản ứng thuận nghịch (hai chiều).<br>• (d) <b>Sai:</b> Chất béo chứa nhiều gốc acid béo không no ở thể lỏng (dầu thực vật); chất béo chứa nhiều gốc no mới ở thể rắn (mỡ động vật).<br>Có 3 phát biểu đúng là (a), (b), (c).<br>Chọn <b>D</b>."
