        "prompt": "Tiến hành lên men m gam tinh bột (hiệu suất toàn quá trình đạt 81%) rồi hấp thụ toàn bộ lượng CO<sub>2</sub> sinh ra vào nước vôi trong dư được 70 gam kết tủa. Giá trị của m là",
        "options": {
          "A": "45.",
          "B": "90.",
          "C": "70.",
          "D": "35."
        },
        "answer": "C",
        "explanation": "• Nước vôi trong dư nên n(CO<sub>2</sub>) = n(CaCO<sub>3</sub>) = 70 / 100 = 0,7 mol.<br>• Sơ đồ lên men:<br>(C<sub>6</sub>H<sub>10</sub>O<sub>5</sub>)ₙ ⟶ 2n CO2<br>162n gam ⟶ 2n mol CO2<br>• Khối lượng tinh bột theo lý thuyết là: m(lt) = (0,7 / 2) × 162 = 56,7 gam.<br>• Vì hiệu suất toàn quá trình là 81%, khối lượng tinh bột thực tế cần dùng là:<br>m = 56,7 / 81% = 70 gam.<br>Chọn <b>C</b>."
