        "prompt": "Tiến hành điều chế ethyl acetate theo các bước như hình sau:<br>• <b>Bước 1:</b> Cho 10 mL C<sub>2</sub>H<sub>5</sub>OH (D = 0,78 g/cm³) cùng với 10 mL CH<sub>3</sub>COOH (D = 1,05 g/cm³), vài giọt dung dịch H<sub>2</sub>SO<sub>4</sub> đặc và lắc đều bình cầu.<br>• <b>Bước 2:</b> Đun nóng bình cầu đến 70 °C trong khoảng từ 5 đến 6 phút.<br>• <b>Bước 3:</b> Các chất thu được ở bình nón được thêm tiếp vào 2 mL dung dịch NaCl bão hòa rồi để yên.",
