          "d": "Đun nóng 6 gam acetic acid với 6 gam ethyl alcohol có H<sub>2</sub>SO<sub>4</sub> đặc làm xúc tác. Khối lượng ester tạo thành khi hiệu suất phản ứng đạt 80% là 8,8 gam."
