        "answer": {
          "a": "S",
          "b": "S",
          "c": "S",
          "d": "S"
        },
        "explanation": "• <b>a) Sai:</b> Ở bước 1 mới chỉ trộn các chất ở nhiệt độ phòng, chưa đun nóng nên phản ứng ester hóa chưa xảy ra đáng kể (phản ứng chỉ xảy ra ở bước 2 khi đun nóng với xúc tác acid).<br>• <b>b) Sai:</b> Phản ứng ester hóa đã hoàn thành ở bước 2; tại bước 3, việc thêm dung dịch NaCl bão hòa là để tăng khối lượng riêng của lớp dung dịch nước và làm giảm độ tan của ethyl acetate, giúp ester tách lớp rõ rệt và nổi lên trên.<br>• <b>c) Sai:</b> H<sub>2</sub>SO<sub>4</sub> đặc có khối lượng riêng lớn (D ≈ 1,84 g/cm³) chìm xuống đáy bình và hỗn hợp chưa đồng nhất hoàn toàn khi mới nhỏ vào và lắc nhẹ.<br>• <b>d) Sai:</b> n(CH<sub>3</sub>COOH) = 6/60 = 0,1 mol; n(C<sub>2</sub>H<sub>5</sub>OH) = 6/46 ≈ 0,13 mol > 0,1 mol ⟹ Hiệu suất tính theo CH<sub>3</sub>COOH. Với H = 80%, m(ester) = 0,1 × 0,8 × 88 = 7,04 gam (8,8 gam là kết quả khi hiệu suất đạt 100%)."
