        "explanation": "• <b>a) Sai:</b> Liên kết N–H trong amine có tín hiệu hấp thụ hồng ngoại đặc trưng trong khoảng số sóng 3300 – 3500 cm⁻¹ (vùng 1740 cm⁻¹ là của liên kết C=O). Ngoài ra amine bậc I (1) có 2 mũi hấp thụ còn amine bậc II (2) chỉ có 1 mũi hấp thụ.<br>• <b>b) Đúng:</b> CH<sub>3</sub>CH<sub>2</sub>NH<sub>2</sub> là amine bậc I (nhóm –NH<sub>2</sub> liên kết với 1 gốc alkyl); CH3–NH–CH3 là amine bậc II (nhóm –NH– liên kết với 2 gốc alkyl).<br>• <b>c) Đúng:</b> Dùng dung dịch HNO2 ở nhiệt độ thường, ethylamine (amine bậc I) phản ứng giải phóng bọt khí N<sub>2</sub> (C<sub>2</sub>H<sub>5</sub>NH<sub>2</sub> + HNO2 ⟶ C<sub>2</sub>H<sub>5</sub>OH + N<sub>2</sub>↑ + H<sub>2</sub>O); còn dimethylamine (amine bậc II) tạo hợp chất nitrosoamine màu vàng và không có khí thoát ra.<br>• <b>d) Sai:</b> n(N<sub>2</sub>) = 4,958 / 24,79 = 0,2 mol ⟹ n(N) = 0,4 mol. Vì hai amine đều đơn chức nên n(hỗn hợp) = 0,4 mol. Lượng HCl phản ứng vừa đủ phải là n(HCl) = n(hỗn hợp) = 0,4 mol (ứng với 400 mL dung dịch HCl 1M, không phải 200 mL)."
