        "explanation": "• Sơ đồ phản ứng: C<sub>6</sub>H<sub>6</sub> (M = 78) ⟶ C<sub>6</sub>H<sub>5</sub>NO<sub>2</sub> ⟶ C<sub>6</sub>H<sub>5</sub>NH<sub>2</sub> (M = 93).<br>• Đổi 1 tấn benzene = 1000 kg benzene.<br>• Khối lượng aniline tạo thành theo lí thuyết:<br>m_aniline(lt) = (1000 · 93) / 78 ≈ 1192,308 kg.<br>• Do hiệu suất của toàn bộ quá trình là H = 60%, khối lượng aniline thực tế thu được là:<br>m_aniline(tt) = 1192,308 · 60% ≈ 715,38 kg.<br>Làm tròn đến hàng đơn vị được 715 kg.<br>Vậy đáp số là <b>715</b>."
