        "question": "Đun nóng chất H<sub>2</sub>N-CH<sub>2</sub>-CONH-CH(CH<sub>3</sub>)-CONH-CH<sub>2</sub>-COOH trong dung dịch HCl (dư), sau khi các phản ứng kết thúc thu được sản phẩm là:",
