          "C": "H<sub>3</sub>N<sup>+</sup>-CH<sub>2</sub>-COOH Cl<sup>-</sup>, H<sub>3</sub>N<sup>+</sup>-CH(CH<sub>3</sub>)-COOH Cl<sup>-</sup>.",
