        "answer": "B",
        "explanation": "Phân tích 4 chất: phenol (C<sub>6</sub>H<sub>5</sub>OH), aniline (C<sub>6</sub>H<sub>5</sub>NH<sub>2</sub>), methylamine (CH<sub>3</sub>NH<sub>2</sub>), ammonia (NH<sub>3</sub>):<br>• Phenol có tính acid yếu nên dung dịch có pH < 7 (pH = 6,48) và nhiệt độ sôi cao 182 °C ⟹ X là C<sub>6</sub>H<sub>5</sub>OH.<br>• Aniline là amine thơm lỏng ở nhiệt độ thường, sôi ở 184 °C, tính base rất yếu nên dung dịch 0,001 M có pH = 7,82 ⟹ Y là C<sub>6</sub>H<sub>5</sub>NH<sub>2</sub>.<br>• Hai chất khí có nhiệt độ sôi âm: CH<sub>3</sub>NH<sub>2</sub> (sôi ở −6,7 °C) và NH<sub>3</sub> (sôi ở −33,4 °C). Do gốc methyl đẩy electron làm tăng tính base nên dung dịch CH<sub>3</sub>NH<sub>2</sub> có pH cao hơn NH<sub>3</sub> (10,81 > 10,12) ⟹ Z là CH<sub>3</sub>NH<sub>2</sub> và T là NH<sub>3</sub>.<br>Vậy nhận xét đúng là: Z là CH<sub>3</sub>NH<sub>2</sub>.<br>Chọn <b>B</b>."
