        "explanation": "• <b>a) Đúng:</b> Aspirin là acetylsalicylic acid (CH<sub>3</sub>COO–C<sub>6</sub>H<sub>4</sub>–COOH) có công thức phân tử là C<sub>9</sub>H<sub>8</sub>O<sub>4</sub>.<br>• <b>b) Đúng:</b> Salicylic acid là 2-hydroxybenzoic acid (HO–C<sub>6</sub>H<sub>4</sub>–COOH) có công thức phân tử là C<sub>7</sub>H<sub>6</sub>O<sub>3</sub>.<br>• <b>c) Sai:</b> Phân tử aspirin có độ bất bão hòa k = (2 · 9 + 2 − 8) / 2 = 6 (gồm 1 vòng benzene, 3 liên kết π trong vòng benzene, 1 liên kết π trong nhóm ester –COO– và 1 liên kết π trong nhóm carboxyl –COOH).<br>• <b>d) Sai:</b> Khối lượng aspirin trong 3 triệu viên là: 3·10⁶ · 81 mg = 243 kg (n = 243 / 180 = 1,35 kmol). Khối lượng salicylic acid cần dùng thực tế với hiệu suất H = 70% là: m = (1,35 · 138) / 70% ≈ 266,14 kg (khác 260 kg)."
