        "prompt": "Cho các thí nghiệm sau:<br>(a) Glucose phản ứng với thuốc thử Tollens.<br>(b) Glucose phản ứng với nước bromine.<br>(c) Glucose phản ứng với copper(II) hydroxide và NaOH đun nóng.<br>(d) Saccharose phản ứng với copper(II) hydroxide trong môi trường kiềm ở điều kiện thường.<br>(e) Cellulose phản ứng với HNO<sub>3</sub> đặc có mặt H<sub>2</sub>SO<sub>4</sub> đặc, đun nóng.<br>Có bao nhiêu thí nghiệm xảy ra phản ứng oxi hóa – khử?",
        "question": "Cho các thí nghiệm sau:<br>(a) Glucose phản ứng với thuốc thử Tollens.<br>(b) Glucose phản ứng với nước bromine.<br>(c) Glucose phản ứng với copper(II) hydroxide và NaOH đun nóng.<br>(d) Saccharose phản ứng với copper(II) hydroxide trong môi trường kiềm ở điều kiện thường.<br>(e) Cellulose phản ứng với HNO<sub>3</sub> đặc có mặt H<sub>2</sub>SO<sub>4</sub> đặc, đun nóng.<br>Có bao nhiêu thí nghiệm xảy ra phản ứng oxi hóa – khử?",
